//! One `Attrs` struct per element in the composed schema, written to `OUT_DIR`.
//!
//! The schema is the single source of truth for what an element's attributes
//! are, which are required, and what their kinds and defaults are. This script
//! turns it into the typed readers the elements use, so lowering never
//! restates a presence rule or a default.
//!
//! Nothing under `src/` is written: the generated file lives in `OUT_DIR` and
//! `espforge_elements::generated` includes it, so a build leaves `git status`
//! clean.

use std::fmt::Write as _;
use std::path::PathBuf;

use espforge_schema::{AttrDef, AttrKind, Element, SchemaError};

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    // The schema file and the crate that reads it: a change to either changes
    // what this script generates.
    println!("cargo:rerun-if-changed=../espforge-schema/src/espf.schema.kdl");
    println!("cargo:rerun-if-changed=../espforge-schema/src/services.schema.kdl");
    println!("cargo:rerun-if-changed=../espforge-schema/src/lib.rs");
    println!("cargo:rerun-if-changed=../espforge-drivers/drivers.schema.kdl");
    println!("cargo:rerun-if-changed=../espforge-drivers/src/lib.rs");

    // The same composed schema `crate::schema::schema()` parses at runtime: a
    // device element in `espforge-drivers` gets its typed `Attrs` here too.
    let schema = espforge_schema::load_all(&[
        espforge_schema::SCHEMA_KDL,
        espforge_schema::SERVICES_SCHEMA_KDL,
        espforge_drivers::DRIVERS_SCHEMA_KDL,
    ])
    .unwrap_or_else(|errors: Vec<SchemaError>| {
        let mut text = String::from("the composed schema does not load:");
        for error in errors {
            let _ = write!(text, "\n  {}: {}", error.span.start, error.message);
        }
        panic!("{text}")
    });

    let mut out = String::from(
        "// AUTO-GENERATED BY BUILD.RS FROM THE COMPOSED SCHEMA - DO NOT EDIT MANUALLY\n\
         //\n\
         // One `Attrs` struct per element in `espf.schema.kdl`,\n\
         // `services.schema.kdl` and `espforge-drivers/drivers.schema.kdl`:\n\
         // every attribute coerced to its\n\
         // declared `kind`, with the span it was written at. Lowering consumes\n\
         // these; the coercion itself is in `crate::attrs`.\n",
    );
    for element in &schema.elements {
        out.push('\n');
        out.push_str(&element_module(element));
    }
    out.push('\n');
    out.push_str(&validate_function(&schema));

    let dest = PathBuf::from(
        std::env::var("OUT_DIR").expect("cargo always sets OUT_DIR for a build script"),
    )
    .join("element_attrs.rs");
    std::fs::write(&dest, out).unwrap_or_else(|e| panic!("cannot write {}: {e}", dest.display()));
}

/// The `validate` dispatcher: the typed `Attrs` readers, reachable by tag.
///
/// The generic device tier knows no tag at compile time, but it must not
/// restate a presence rule or a `choice` list the schema already owns. This
/// function is the seam: it calls the same `Attrs::from_node` a hand-written
/// element does, and hands back only the `Issue` the caller turns into the
/// element's own wording.
fn validate_function(schema: &espforge_schema::Schema) -> String {
    let mut out = String::from(
        "/// Validate `node` against the attributes the schema declares for `tag`.\n\
         ///\n\
         /// `None` when the tag has no generated `Attrs`, which cannot happen for\n\
         /// an element in the schema.\n\
         pub fn validate<'a>(\n\
         \x20   tag: &str,\n\
         \x20   node: &'a espf::context::ParsedNode<'a>,\n\
         ) -> Option<Result<(), crate::attrs::Issue<'a>>> {\n\
         \x20   match tag {\n",
    );
    for element in &schema.elements {
        let tag = &element.tag;
        let _ = writeln!(
            out,
            "        {tag:?} => Some({tag}::Attrs::from_node(node).map(|_| ())),"
        );
    }
    out.push_str("        _ => None,\n    }\n}\n");
    out
}

/// One `pub mod <tag> { ... }` with the element's enums and `Attrs` struct.
fn element_module(element: &Element) -> String {
    let tag = &element.tag;
    let mut enums: Vec<String> = Vec::new();
    let mut fields: Vec<String> = Vec::new();
    let mut inits: Vec<String> = Vec::new();
    let mut borrowed = false;

    for attr in &element.attrs {
        let (ty, init) = field_type(tag, attr, &mut enums);
        let presence = match (attr.required, attr.default.as_deref()) {
            (true, _) => "required".to_string(),
            (false, Some(default)) => format!("optional, default {default:?}"),
            (false, None) => "optional".to_string(),
        };
        let field = field_name(&attr.name);
        borrowed |= ty.contains("'a");
        fields.push(format!(
            "    /// `{}` (`{}`, {presence})\n    pub {field}: {ty},",
            attr.name,
            attr.kind.display()
        ));
        inits.push(format!("            {field}: {init},"));
    }

    // An element whose attributes are all owned values (`<runtime type=...>`)
    // borrows nothing, so it needs no lifetime parameter.
    let (struct_head, impl_head, fn_head) = if borrowed {
        (
            "pub struct Attrs<'a> {",
            "impl<'a> Attrs<'a> {",
            "pub fn from_node(node: &'a ParsedNode<'a>) -> Result<Self, Issue<'a>> {",
        )
    } else {
        (
            "pub struct Attrs {",
            "impl Attrs {",
            "pub fn from_node<'n>(node: &'n ParsedNode<'n>) -> Result<Self, Issue<'n>> {",
        )
    };

    let mut body = String::new();
    for definition in &enums {
        body.push_str(definition);
    }
    let _ = write!(
        body,
        "/// `<{tag}>` from `espf.schema.kdl`.\n\
         #[derive(Debug, Clone)]\n\
         {struct_head}\n\
         {fields}\n\
         }}\n\
         \n\
         {impl_head}\n\
         \x20   /// Reads the attributes `espf.schema.kdl` declares for `<{tag}>`.\n\
         \x20   {fn_head}\n\
         \x20       Ok(Self {{\n\
         {inits}\n\
         \x20       }})\n\
         \x20   }}\n\
         }}\n",
        fields = fields.join("\n"),
        inits = inits.join("\n"),
    );

    format!(
        "pub mod {tag} {{\n\
        \x20   use espf::context::ParsedNode;\n\
        \n\
        \x20   use crate::attrs::*;\n\
        \n\
        {}\
         }}\n",
        indent(&body, 4)
    )
}

/// The Rust type and initialiser for one declared attribute.
///
/// Only the kinds the phase-1 schema declares have a mapping. Any other kind
/// panics here rather than guessing: it arrives with the element that first
/// uses it, together with its coercion helper.
fn field_type(tag: &str, attr: &AttrDef, enums: &mut Vec<String>) -> (String, String) {
    let name = &attr.name;
    let lit = format!("{name:?}");
    match (&attr.kind, attr.required, attr.default.as_deref()) {
        (AttrKind::Ident, true, _) => (
            "Spanned<&'a str>".to_string(),
            format!("ident(node, {lit})?"),
        ),
        (AttrKind::Str, true, _) => (
            "Spanned<&'a str>".to_string(),
            format!("text(node, {lit})?"),
        ),
        (AttrKind::Str, false, Some(default)) => (
            "Spanned<&'a str>".to_string(),
            format!("text_or(node, {lit}, {default:?})?"),
        ),
        (AttrKind::Str, false, None) => (
            "Option<Spanned<&'a str>>".to_string(),
            format!("opt_text(node, {lit})?"),
        ),
        (AttrKind::Freq, true, _) => (
            "Spanned<&'a str>".to_string(),
            format!("frequency(node, {lit})?"),
        ),
        (AttrKind::Freq, false, Some(default)) => (
            "Spanned<&'a str>".to_string(),
            format!("frequency_or(node, {lit}, {default:?})?"),
        ),
        (AttrKind::Freq, false, None) => (
            "Option<Spanned<&'a str>>".to_string(),
            format!("opt_frequency(node, {lit})?"),
        ),
        (AttrKind::U32, true, _) => match attr.range {
            Some((low, high)) => (
                "Spanned<u32>".to_string(),
                format!("number_in(node, {lit}, {low}, {high})?"),
            ),
            None => ("Spanned<u32>".to_string(), format!("number(node, {lit})?")),
        },
        (AttrKind::U32, false, Some(default)) => {
            let default: u32 = default
                .parse()
                .unwrap_or_else(|_| panic!("`{tag}.{name}` default `{default}` is not a u32"));
            match attr.range {
                Some((low, high)) => (
                    "Spanned<u32>".to_string(),
                    format!("number_in_or(node, {lit}, {low}, {high}, {default})?"),
                ),
                None => (
                    "Spanned<u32>".to_string(),
                    format!("number_or(node, {lit}, {default})?"),
                ),
            }
        }
        (AttrKind::Hex, true, _) => ("Spanned<u8>".to_string(), format!("hex(node, {lit})?")),
        (AttrKind::Hex, false, None) => (
            "Option<Spanned<u8>>".to_string(),
            format!("opt_hex(node, {lit})?"),
        ),
        (AttrKind::PinOrRef, true, _) => (
            "PinOrRef<'a>".to_string(),
            format!("pin_or_ref(node, {lit})?"),
        ),
        (AttrKind::Pin, true, _) => ("Spanned<u8>".to_string(), format!("pin(node, {lit})?")),
        (AttrKind::Pin, false, None) => (
            "Option<Spanned<u8>>".to_string(),
            format!("opt_pin(node, {lit})?"),
        ),
        (AttrKind::Bool, true, _) => ("Spanned<bool>".to_string(), format!("flag(node, {lit})?")),
        (AttrKind::Bool, false, Some(default)) => {
            let default = match default {
                "true" => "true",
                "false" => "false",
                other => panic!("`{tag}.{name}` has non-boolean default `{other}`"),
            };
            (
                "Spanned<bool>".to_string(),
                format!("flag_or(node, {lit}, {default})?"),
            )
        }
        (AttrKind::Ref { .. }, true, _) => {
            ("Ref<'a>".to_string(), format!("reference(node, {lit})?"))
        }
        (AttrKind::Ref { .. }, false, None) => (
            "Option<Ref<'a>>".to_string(),
            format!("opt_reference(node, {lit})?"),
        ),
        (AttrKind::Choice(choices), required, default) => {
            if choices.is_empty() {
                panic!("choice attribute `{tag}.{name}` has no `choices`");
            }
            let enum_name = camel_case(&field_name(name));
            enums.push(choice_enum(&enum_name, name, choices));
            match (required, default) {
                (true, _) => (
                    format!("Spanned<{enum_name}>"),
                    format!("parsed(node, {lit}, {enum_name}::parse)?"),
                ),
                (false, Some(default)) => (
                    format!("Spanned<{enum_name}>"),
                    format!(
                        "parsed_or(node, {lit}, {enum_name}::parse, {enum_name}::{})?",
                        variant_name(default)
                    ),
                ),
                (false, None) => (
                    format!("Option<Spanned<{enum_name}>>"),
                    format!("opt_parsed(node, {lit}, {enum_name}::parse)?"),
                ),
            }
        }
        (kind, required, default) => panic!(
            "unsupported attribute on `{tag}.{name}`: kind `{}`, required {required}, default {default:?}",
            kind.display()
        ),
    }
}

/// A generated enum for one `kind="choice"` attribute.
fn choice_enum(enum_name: &str, attr_name: &str, choices: &[String]) -> String {
    let variants: Vec<String> = choices.iter().map(|c| variant_name(c)).collect();

    let mut decls = String::new();
    let mut parses = String::new();
    let mut spellings = String::new();
    for (choice, variant) in choices.iter().zip(&variants) {
        let _ = write!(decls, "    /// `{choice}`\n    {variant},\n");
        let _ = write!(parses, "            {choice:?} => Some(Self::{variant}),\n");
        let _ = write!(spellings, "            Self::{variant} => {choice:?},\n");
    }

    let quoted: Vec<String> = choices.iter().map(|c| format!("{c:?}")).collect();

    format!(
        "/// The `{attr_name}` values `espf.schema.kdl` allows.\n\
         #[derive(Debug, Clone, Copy, PartialEq, Eq)]\n\
         pub enum {enum_name} {{\n\
         {decls}\
         }}\n\
         \n\
         impl {enum_name} {{\n\
         \x20   /// The accepted spellings, in schema order.\n\
         \x20   pub const CHOICES: &'static [&'static str] = &[{choices}];\n\
         \n\
         \x20   /// Parses one of `CHOICES`; `None` for anything else.\n\
         \x20   pub fn parse(raw: &str) -> Option<Self> {{\n\
         \x20       match raw {{\n\
         {parses}\
         \x20           _ => None,\n\
         \x20       }}\n\
         \x20   }}\n\
         \n\
         \x20   /// The ESPF spelling of this value.\n\
         \x20   pub fn as_str(self) -> &'static str {{\n\
         \x20       match self {{\n\
         {spellings}\
         \x20       }}\n\
         \x20   }}\n\
         }}\n\
         \n",
        choices = quoted.join(", "),
    )
}

/// `"StopBits"`-style name for an attribute's generated enum.
fn camel_case(text: &str) -> String {
    let mut out = String::new();
    for part in text.split(|c: char| !c.is_ascii_alphanumeric()) {
        let mut chars = part.chars();
        if let Some(first) = chars.next() {
            out.extend(first.to_uppercase());
            out.push_str(&chars.as_str().to_lowercase());
        }
    }
    out
}

/// An enum variant for one `choices` spelling; `1` becomes `N1`, since a
/// variant cannot start with a digit.
fn variant_name(choice: &str) -> String {
    let name = camel_case(choice);
    if name.starts_with(|c: char| c.is_ascii_digit()) {
        format!("N{name}")
    } else {
        name
    }
}

/// A Rust field name for a schema attribute name (`network1.ssid` becomes
/// `network1_ssid`; keywords get a trailing `_`).
fn field_name(attr: &str) -> String {
    let name: String = attr
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() { c } else { '_' })
        .collect();
    if is_keyword(&name) {
        format!("{name}_")
    } else {
        name
    }
}

fn is_keyword(name: &str) -> bool {
    matches!(
        name,
        "as" | "break"
            | "const"
            | "continue"
            | "crate"
            | "dyn"
            | "else"
            | "enum"
            | "extern"
            | "false"
            | "fn"
            | "for"
            | "if"
            | "impl"
            | "in"
            | "let"
            | "loop"
            | "match"
            | "mod"
            | "move"
            | "mut"
            | "pub"
            | "ref"
            | "return"
            | "self"
            | "static"
            | "struct"
            | "super"
            | "trait"
            | "true"
            | "type"
            | "unsafe"
            | "use"
            | "where"
            | "while"
            | "async"
            | "await"
            | "try"
            | "union"
    )
}

/// Prefix every non-empty line of `text` with `spaces` spaces.
fn indent(text: &str, spaces: usize) -> String {
    let pad = " ".repeat(spaces);
    text.lines()
        .map(|line| {
            if line.is_empty() {
                String::from("\n")
            } else {
                format!("{pad}{line}\n")
            }
        })
        .collect()
}
